const status=document.querySelector('#status'),connect=document.querySelector('#connect'),confirm=document.querySelector('#confirm');
async function request(path,body){const r=await fetch('/api/scorestarling'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await r.json();if(!r.ok)throw Error(data.error);return data;}
const params=new URLSearchParams(location.search);document.querySelector('#title').value=params.get('title')||sessionStorage.getItem('scorestarling-title')||'';document.querySelector('#url').value=params.get('url')||sessionStorage.getItem('scorestarling-url')||'';
request('').then(data=>{status.textContent=data.connected?'账号已连接':'连接账号后，可以将歌曲链接转成电子谱。';connect.hidden=data.connected;}).catch(e=>status.textContent=e.message);
connect.onclick=async()=>{connect.disabled=true;try{sessionStorage.setItem('scorestarling-title',document.querySelector('#title').value);sessionStorage.setItem('scorestarling-url',document.querySelector('#url').value);const data=await request('/connect',{});location.assign(data.url);}catch(e){status.textContent=e.message;connect.disabled=false;}};
let job=sessionStorage.getItem('scorestarling-job'),timer=null;
if(job)void poll();
async function poll(){try{const data=await request('?id='+encodeURIComponent(job));status.textContent=data.detail||'正在处理';document.querySelector('#progress').value=data.progress||0;if(data.status==='complete'){clearTimeout(timer);document.querySelector('#submit').disabled=false;const link=document.createElement('a');link.href='/';link.textContent='已加入云曲库，返回工作区';status.replaceChildren(link);return;}if(data.status==='failed'){document.querySelector('#submit').disabled=false;return;}if(data.credits!=null&&data.status==='queued'){confirm.hidden=false;confirm.textContent=`使用 ${data.credits} 积分导出 MusicXML`;confirm.onclick=async()=>{confirm.disabled=true;try{await request('/import',{id:job,credits:data.credits,consent:true});confirm.hidden=true;timer=setTimeout(poll,1200);}catch(e){status.textContent=e.message;}finally{confirm.disabled=false;}};return;}timer=setTimeout(poll,1800);}catch(e){status.textContent=e.message;document.querySelector('#submit').disabled=false;}}
document.querySelector('#form').onsubmit=async e=>{e.preventDefault();document.querySelector('#submit').disabled=true;confirm.hidden=true;try{const data=await request('/import',{title:document.querySelector('#title').value,url:document.querySelector('#url').value});job=data.id;sessionStorage.setItem('scorestarling-job',job);void poll();}catch(e){status.textContent=e.message;document.querySelector('#submit').disabled=false;}};
